@startuml

class Student {
  + studentID : int
  + dateOfBirth : date
  + city : string
  + region : string
  + yearOfEnrollment : int
}

class Professor {
  + name : string
  + dateOfBirth : date
  + city : string
}

class Faculty {
  + name : string
  + type : string
}

class Course {
  + code : int
  + lectureHours : int
}

class Exam {
  + grade : string
}

Student "1" -- "1" Faculty : is enrolled in
Professor "1" -- "*" Course : teaches
Course "*" -- "1" Faculty : belongs to
Student "1" -- "*" Exam : passes
Exam "*" -- "1" Course : for

@enduml

